import Foundation

/// Rules for clips: what kind a copy is, what a row shows, what search
/// matches, and which copies are never saved.
public enum ClipRules {
    /// Pasteboard types password managers and system tools set to say
    /// "don't keep this" (nspasteboard.org).
    public static let skippedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
    ]

    /// Apps whose copies are never saved.
    public static let excludedApps: Set<String> = [
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.apple.keychainaccess",
        "com.apple.Passwords",
        "com.bitwarden.desktop",
    ]

    /// The most clips kept, not counting pinned ones.
    public static let historyLimit = 500
    /// Larger images are skipped.
    public static let maxImageBytes = 10 * 1024 * 1024

    public static func shouldSkip(types: [String], sourceApp: String?) -> Bool {
        if types.contains(where: skippedTypes.contains) { return true }
        if let sourceApp, excludedApps.contains(sourceApp) { return true }
        return false
    }

    /// True for a single http or https URL with a host, nothing else.
    public static func isLink(_ text: String) -> Bool {
        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.contains(where: \.isWhitespace),
              let url = URL(string: trimmed),
              let scheme = url.scheme?.lowercased(), scheme == "http" || scheme == "https",
              let host = url.host(), !host.isEmpty else { return false }
        return true
    }

    /// One line for a row: whitespace runs collapsed, at most `limit` characters.
    public static func preview(_ text: String, limit: Int = 200) -> String {
        let line = text.split(whereSeparator: \.isWhitespace).joined(separator: " ")
        return line.count > limit ? String(line.prefix(limit)) + "…" : line
    }

    /// Search matches anywhere in the text, ignoring case and accents.
    public static func matches(_ query: String, text: String) -> Bool {
        let q = query.trimmingCharacters(in: .whitespaces)
        guard !q.isEmpty else { return true }
        return text.range(of: q, options: [.caseInsensitive, .diacriticInsensitive]) != nil
    }

    /// Which clips to delete so at most `limit` unpinned clips remain.
    /// `clips` is newest first; pinned clips are never chosen.
    public static func pruned<ID>(_ clips: [(id: ID, isPinned: Bool)], limit: Int = historyLimit) -> [ID] {
        clips.filter { !$0.isPinned }.dropFirst(limit).map(\.id)
    }
}
